{"source": "def investigate(context, acquire):
    hist = acquire("history")

    def simulate(actions, mode, chan, trig):
        committed = {}
        txn = {"main": None, "other": None}
        tc = {"main": 0, "other": 0}
        last_changes = 0

        def put_direct(key, value):
            if mode == "ignore":
                if key not in committed:
                    committed[key] = value
                    return 1
                return 0
            committed[key] = value
            return 1

        def upd_direct(key, value):
            if key in committed:
                committed[key] = value
                return 1
            return 0

        def del_direct(key):
            if key in committed:
                del committed[key]
                return 1
            return 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                txn[conn] = {}
            elif op == "commit":
                if txn[conn] is not None:
                    for k, v in txn[conn].items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                    txn[conn] = None
            elif op == "rollback":
                txn[conn] = None
            elif op in ("put", "update", "delete"):
                key = act.get("key")
                value = act.get("value")
                buf = txn[conn]
                if buf is not None:
                    if op == "put":
                        if mode == "ignore":
                            if key not in committed and key not in buf:
                                buf[key] = value
                                direct = 1
                            else:
                                direct = 0
                        else:
                            buf[key] = value
                            direct = 1
                    elif op == "update":
                        if key in committed or key in buf:
                            buf[key] = value
                            direct = 1
                        else:
                            direct = 0
                    else:
                        if key in committed or key in buf:
                            buf[key] = None
                            direct = 1
                        else:
                            direct = 0
                else:
                    if op == "put":
                        direct = put_direct(key, value)
                    elif op == "update":
                        direct = upd_direct(key, value)
                    else:
                        direct = del_direct(key)
                trigc = 1 if (trig and direct == 1) else 0
                tc[conn] += direct + trigc
                if conn == "main":
                    last_changes = direct

        if chan == "changes":
            ch = last_changes
        elif chan == "total_main":
            ch = tc["main"]
        else:
            ch = tc["main"] + tc["other"]
        return ch, len(committed), sum(committed.values())

    modes = ["ignore", "replace", "upsert"]
    chans = ["changes", "total_main", "total_both"]
    trigs = [False, True]

    candidates = []
    for mode in modes:
        for chan in chans:
            for trig in trigs:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    ch, cc, cs = simulate(acts, mode, chan, trig)
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((mode, chan, trig))

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for mode, chan, trig in candidates:
        ch, cc, cs = simulate(actions, mode, chan, trig)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
    if len(vals) == 1:
        return {"value": vals.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Simulates all 18 family members (put mode x channel x trigger) and filters by calibration receipts; predicts only when all consistent members agree.", "lesson": "The channel is not net committed effects; changes() counts last direct row changes, total_changes includes trigger inserts, and INSERT OR IGNORE/REPLACE/upsert differ on conflicts."}
